**Finding:** No CORS headers are configured. Express's default is to allow all origins in some configurations, depending on how the app is deployed behind proxies.

**Fix:**

```js
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // Cache preflight for 24 hours
};

app.use(cors(corsOptions));
```

---

### 🟡 MEDIUM — No Centralized Error Handler (OWASP A09)

**Finding:** There is no global error-handling middleware. Unhandled promise rejections and thrown errors will either crash the process or cause Express to leak stack traces in default error responses.

**Fix:**

```js
// Catch-all for unmatched routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler — must have exactly 4 arguments
app.use((err, req, res, next) => {
  // Log full error internally
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
  });

  // Never expose stack traces or internal messages to the client
  const status = err.status ?? err.statusCode ?? 500;
  res.status(status).json({
    error: status < 500 ? err.message : 'Internal server error',
  });
});

// Catch unhandled promise rejections at the process level
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled rejection:', reason);
});
```

