**Problem:** The `/users` endpoint returns a hardcoded list of users with no authentication, no authorization, and no rate limiting. In a real app this would be a live database query, and it would be fully public.

```js
// ❌ Current — unauthenticated, unfiltered data dump
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Fix:** Guard every data endpoint with authentication middleware, and only return fields the caller is authorized to see (field-level authorization).

```js
// ✅ Fixed — JWT-gated, field-filtered
const { expressjwt: jwt } = require('express-jwt');

const requireAuth = jwt({
  secret: process.env.JWT_SECRET,   // never hardcode
  algorithms: ['HS256'],
});

app.get('/users', requireAuth, async (req, res) => {
  // Only admins may list all users
  if (req.auth.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const users = await db.query(
    'SELECT id, name, email FROM users'   // never SELECT *
  );
  res.json(users.rows);
});
```

---

### Finding 2 — No Input Validation on Any Route (High)

**Problem:** The app currently has no query-parameter or body parsing at all. As soon as a developer adds `req.query`, `req.body`, or `req.params` usage, there is nothing stopping injection payloads, oversized payloads, or unexpected types.

**Fix:** Add a validation layer at the framework level using `zod` or `joi` before any handler logic runs.

```js
// ✅ Zod-based query validation middleware
const { z } = require('zod');

function validate(schema, source = 'query') {
  return (req, res, next) => {
    const result = schema.safeParse(req[source]);
    if (!result.success) {
      return res.status(400).json({
        error: 'Invalid input',
        details: result.error.flatten(),
      });
    }
    req.validated = result.data;   // replace raw input with parsed, typed data
    next();
  };
}

// Usage on a hypothetical /users/:id route
const userParamSchema = z.object({
  id: z.coerce.number().int().positive(),
});

app.get('/users/:id', requireAuth, validate(userParamSchema, 'params'), async (req, res) => {
  const { id } = req.validated;           // safe, typed integer — never a string like "1 OR 1=1"
  const user = await db.query('SELECT id, name FROM users WHERE id = $1', [id]);
  // ...
});
```

---

### Finding 3 — No Body Parser / Payload Size Limit (Medium)

**Problem:** There is no `express.json()` middleware and no size cap. An attacker can POST arbitrarily large JSON bodies, causing memory exhaustion (a form of Denial of Service).

**Fix:**

```js
// ✅ Parse JSON bodies with a strict size cap
app.use(express.json({ limit: '16kb' }));    // reject anything larger
app.use(express.urlencoded({ extended: false, limit: '16kb' }));
```

---

### Finding 4 — Missing Security Headers (Medium) — OWASP A05

**Problem:** Express ships with no security headers. Browsers will not receive `Content-Security-Policy`, `X-Frame-Options`, `X-Content-Type-Options`, etc., leaving clients open to XSS, clickjacking, and MIME sniffing attacks.

**Fix:** Drop in `helmet` as the very first middleware.

```js
const helmet = require('helmet');

// ✅ Must be registered BEFORE all routes
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],        // no inline scripts, no CDN unless explicitly trusted
      objectSrc:  ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000,                // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));
```

---

### Finding 5 — No Rate Limiting (Medium) — OWASP A04

**Problem:** Every endpoint accepts unlimited requests. This enables brute-force attacks (especially on future auth endpoints), credential stuffing, and resource exhaustion.

**Fix:**

```js
const rateLimit = require('express-rate-limit');

// ✅ Global limiter
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,   // 15-minute window
  max: 100,                    // max requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
}));

// ✅ Tighter limiter for sensitive routes (login, password reset, etc.)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'Too many authentication attempts.' },
});

app.post('/login', authLimiter, loginHandler);
```

---

### Finding 6 — Information Leakage via Default Error Handling (Medium) — OWASP A09

**Problem:** Express's default error handler sends full stack traces to the client in development mode and may leak framework version information via the `X-Powered-By` header.

**Fix:**

```js
// ✅ Remove the X-Powered-By header (helmet does this too, but be explicit)
app.disable('x-powered-by');

// ✅ Centralized error handler — MUST be the last app.use()
app.use((err, req, res, next) => {
  const requestId = req.headers['x-request-id'] ?? crypto.randomUUID();

  // Log full detail internally (to your log aggregator, never to the client)
  console.error({ requestId, err });

  // Return only a safe, opaque message to the client
  const statusCode = err.statusCode ?? 500;
  res.status(statusCode).json({
    error: statusCode < 500 ? err.message : 'An unexpected error occurred.',
    requestId,   // lets users report issues without exposing internals
  });
});
```

---

### Finding 7 — Secrets Must Come From Environment Variables (Critical) — OWASP A02

**Problem:** The app currently has no secret management at all. As features are added (DB connections, JWT signing keys, third-party API keys), there is a high risk they get hardcoded directly in source.

**Fix:** Establish the pattern now, before any secrets are needed.

```js
// ✅ Load at the very top of app.js (or a dedicated config.js)
require('dotenv').config();                        // reads from .env (never committed to git)

function requireEnv(name) {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable: ${name}`);
  return value;
}

const config = {
  port:      parseInt(process.env.PORT ?? '3000', 10),
  jwtSecret: requireEnv('JWT_SECRET'),
  dbUrl:     requireEnv('DATABASE_URL'),
};

// .env is listed in .gitignore; .env.example (with placeholder values) is committed instead
```

**Also ensure `.gitignore` contains:**
```
.env
.env.*
!.env.example
```

---

### Finding 8 — No CORS Policy (Medium) — OWASP A01

**Problem:** By default Express does not set CORS headers, so the behavior depends entirely on the deployment environment. If a permissive proxy is in front, any origin can make credentialed cross-site requests.

**Fix:**

```js
const cors = require('cors');

// ✅ Explicit allowlist — never use cors() with no options in production
app.use(cors({
  origin: (origin, callback) => {
    const allowed = (process.env.ALLOWED_ORIGINS ?? '').split(',');
    if (!origin || allowed.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: origin '${origin}' not allowed`));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Authorization', 'Content-Type'],
  credentials: true,
  maxAge: 86400,   // cache preflight for 24 hours
}));
```

---

### Finding 9 — `/health` Endpoint Leaks Timing Information (Low)

**Problem:** `new Date().toISOString()` in the health endpoint is low-risk today, but server timestamps can help attackers correlate log entries or fingerprint infrastructure. At scale, health endpoints should also be protected from abuse.

**Fix:**

```js
// ✅ Return only what a load balancer needs — nothing more
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});
```

---

## Summary Table

| # | Vulnerability | OWASP Category | Severity | Fix |
|---|---|---|---|---|
| 1 | Unauthenticated `/users` endpoint | A01 Broken Access Control | 🔴 High | Add JWT middleware + role check |
| 2 | No input validation | A03 Injection | 🔴 High | Add `zod`/`joi` validation middleware |
| 3 | No body-parser / payload size limit | A04 Insecure Design | 🟠 Medium | `express.json({ limit: '16kb' })` |
