// Simple IP allowlist middleware for internal routes
function requireInternalNetwork(req, res, next) {
  const allowedCIDRs = (process.env.INTERNAL_CIDR || '').split(',');
  // Use a library like `ipaddr.js` for real CIDR matching
  const clientIP = req.ip;
  if (!allowedCIDRs.some(cidr => isInRange(clientIP, cidr))) {
    return res.status(404).end(); // Return 404, not 403, to avoid confirming the route exists
  }
