**Recommendation:**
```js
const helmet = require('helmet'); // npm install helmet

app.use(helmet()); // Sensible secure defaults in one line

// Or configure granularly:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
    },
