```js
const express = require('express');
const { query, validationResult } = require('express-validator'); // npm install express-validator

app.use(express.json({ limit: '10kb' }));         // Parse JSON bodies, cap size
app.use(express.urlencoded({ extended: false })); // Parse form bodies

// Example: validate a future query param
app.get('/users', requireAuth, [
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
], (req, res) => {
  const errors = validationResult(req);
