**Recommendation:**
```js
// Use a parameterized query layer — never string-concatenate user input into queries
const { Pool } = require('pg'); // npm install pg
const db = new Pool({ connectionString: process.env.DATABASE_URL });

app.get('/users', requireAuth, async (req, res, next) => {
  try {
    const { page = 1, limit = 20 } = req.query;
    const offset = (page - 1) * limit;

    // ✅ Parameterized — immune to SQL injection
    const { rows } = await db.query(
      'SELECT id, name FROM users LIMIT $1 OFFSET $2', // Never SELECT * — return only needed fields
      [limit, offset]
    );
    res.json(rows);
  } catch (err) {
    next(err); // Let the centralized error handler respond safely
  }
});
```

