```js
// ✅ Add helmet — sets 11 security headers in one line
const helmet = require('helmet');
app.use(helmet());
// This sets: Content-Security-Policy, X-DNS-Prefetch-Control,
// X-Frame-Options, X-Permitted-Cross-Domain-Policies,
// Referrer-Policy, X-Content-Type-Options (nosniff),
// Origin-Agent-Cluster, X-Download-Options, X-XSS-Protection,
// removes X-Powered-By

// For APIs, you can be more surgical:
app.use(helmet({
  contentSecurityPolicy: false, // relax if serving HTML too
}));
app.disable('x-powered-by'); // at minimum, always do this
```

