// and gives inconsistent responses in production
```

```js
// ✅ Add a centralized error handler as the LAST middleware
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // Always log the full error server-side
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Never expose internals to clients in production
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'An unexpected error occurred',
    ...(isDev && { stack: err.stack }),
  });
});

// Also handle unhandled promise rejections
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // optionally: process.exit(1) to let process manager restart cleanly
});
```

