A `.env.test` file containing database passwords, cloud-provider keys, and payment-processor secrets lives in the same directory as the application. Secret files must never be committed to source control or left accessible on disk next to app code.

**Fix:**
```bash
# 1. Add to .gitignore immediately
echo ".env*" >> .gitignore
echo "*.env" >> .gitignore

# 2. Verify the file isn't already tracked
git rm --cached .env.test
```
```javascript
// 3. Load secrets at runtime via environment variables only — never from a
//    file that travels with the code. Use a secrets manager in production.
const { DATABASE_URL } = process.env;
if (!DATABASE_URL) throw new Error('DATABASE_URL is required');
```

---

### Finding 2 — No Authentication or Authorization on Any Route
**Severity: 🔴 Critical | OWASP A01: Broken Access Control**

`GET /users` returns user data — including email addresses — to any caller, with zero authentication. There is no concept of identity anywhere in the app.

**Fix — add JWT-based auth middleware:**
```javascript
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) throw new Error('JWT_SECRET env var is required');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }
  const token = authHeader.slice(7);
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Apply to sensitive routes
app.get('/users', requireAuth, (req, res) => { /* ... */ });
```

---

### Finding 3 — No Input Validation or Sanitization
**Severity: 🔴 Critical | OWASP A03: Injection**

The app has no body parsing and no query-parameter validation. Any future route that reads `req.query`, `req.body`, or `req.params` without validation is a direct injection vector (SQL, NoSQL, command, path traversal, etc.).

**Fix — validate at the boundary before any business logic:**
```javascript
const { z } = require('zod'); // or use joi, express-validator, etc.

// Define a schema once; reuse everywhere
const UserQuerySchema = z.object({
  page:  z.coerce.number().int().min(1).max(1000).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

app.get('/users', requireAuth, (req, res) => {
  const result = UserQuerySchema.safeParse(req.query);
  if (!result.success) {
    return res.status(400).json({ error: 'Invalid query parameters', details: result.error.issues });
  }
  const { page, limit } = result.data;
  // use only the validated, typed values from here on
});
```

---

### Finding 4 — Missing Security Headers
**Severity: 🟠 High | OWASP A05: Security Misconfiguration**

Express ships with no security headers by default. Without them, browsers have no protection against XSS, clickjacking, MIME sniffing, or protocol downgrade attacks.

**Fix — add `helmet` as the very first middleware:**
```javascript
const helmet = require('helmet');

// Must be registered before any route handler
app.use(helmet());                       // sets 14 headers in one call
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true })); // force HTTPS
```
Key headers `helmet` enables:
| Header | Protection |
|---|---|
| `Content-Security-Policy` | XSS, data injection |
| `X-Frame-Options` | Clickjacking |
| `X-Content-Type-Options` | MIME sniffing |
| `Referrer-Policy` | Information leakage |
| `Strict-Transport-Security` | Protocol downgrade |

---

### Finding 5 — No Rate Limiting
**Severity: 🟠 High | OWASP A07: Identification & Authentication Failures**

Every endpoint accepts unlimited requests. This enables brute-force attacks against any future auth endpoint, credential stuffing, and trivial denial-of-service.

**Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // much tighter on auth endpoints
  message: { error: 'Too many login attempts.' },
});

app.use(globalLimiter);
app.post('/auth/login', authLimiter, loginHandler);
```

---

### Finding 6 — Verbose Error Leakage / No Centralized Error Handler
**Severity: 🟠 High | OWASP A05: Security Misconfiguration**

Express's default error handler dumps a full stack trace — including file paths, dependency versions, and internal logic — to the client in development *and* production unless explicitly overridden.

**Fix — add a production-safe error handler as the last middleware:**
```javascript
// Catch async errors in route handlers
const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

// Centralized error handler — MUST have 4 parameters for Express to recognize it
app.use((err, req, res, next) => {
  const requestId = req.headers['x-request-id'] ?? crypto.randomUUID();
  // Log the full error internally (to your logging system, never to the client)
  console.error({ requestId, err });

  const statusCode = err.statusCode ?? 500;
  res.status(statusCode).json({
    error: statusCode < 500 ? err.message : 'An internal error occurred',
    requestId, // gives ops a correlation handle without exposing internals
  });
});
```

---

### Finding 7 — No CORS Policy
**Severity: 🟠 High | OWASP A05: Security Misconfiguration**

With no CORS configuration, cross-origin behaviour is determined entirely by the browser's defaults, which is unpredictable. An explicit allowlist should always be defined.

**Fix:**
```javascript
const cors = require('cors');

const allowedOrigins = (process.env.ALLOWED_ORIGINS ?? '').split(',').filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    // Allow server-to-server calls (no origin) or listed origins
    if (!origin || allowedOrigins.includes(origin)) return callback(null, true);
    callback(new Error(`CORS: origin '${origin}' is not allowed`));
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Authorization', 'Content-Type'],
  credentials: true,
  maxAge: 86400,
}));
```

---

### Finding 8 — Hardcoded, Unversioned User Data
**Severity: 🟡 Medium | OWASP A02 / A04: Insecure Design**

User records are baked into the route handler. Real applications use a database with parameterized queries. Hardcoded data makes injection risks invisible because there's no query layer to audit — but it also establishes bad patterns for when a database is inevitably added.

**Fix — use parameterized queries from day one:**
```javascript
// With pg (node-postgres) — NEVER interpolate user input into query strings
async function getUserById(id) {
  // $1 is a bound parameter — the driver handles escaping; SQL injection is impossible
  const { rows } = await db.query('SELECT id, name, email FROM users WHERE id = $1', [id]);
  return rows[0] ?? null;
}

// With an ORM (Prisma example)
const user = await prisma.user.findUnique({ where: { id: Number(id) } });
```

---

### Finding 9 — No Request Body Size Limit
**Severity: 🟡 Medium | OWASP A05: Security Misconfiguration**

Once a JSON body parser is added, the default Express/Node behaviour allows arbitrarily large request bodies, enabling memory exhaustion attacks.

**Fix:**
```javascript
app.use(express.json({ limit: '10kb' }));    // reject payloads over 10 KB
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### Finding 10 — No Security Logging or Audit Trail
**Severity: 🟡 Medium | OWASP A09: Security Logging & Monitoring Failures**

There is no logging of requests, errors, or security events. Without this, breaches cannot be detected or investigated.

**Fix:**
```javascript
const morgan = require('morgan');

// Log all requests in a structured format
app.use(morgan('combined'));

// Additionally, log security-relevant events explicitly
function logSecurityEvent(event, req, meta = {}) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    event,
    ip: req.ip,
    method: req.method,
    path: req.path,
    userId: req.user?.id ?? null,
    ...meta,
  }));
}

// Usage inside route handlers:
// logSecurityEvent('AUTH_FAILURE', req, { reason: 'invalid_token' });
// logSecurityEvent('ACCESS_DENIED', req, { resource: '/users' });
```

---

