### 5. No Request Body Parsing or Input Validation (OWASP A03)

**Problem:** There is no `express.json()` middleware, so POST/PUT bodies are silently ignored. When body parsing is added, there's no validation — opening the door to injection attacks, oversized payloads, and malformed data.

**Recommendation:** Add body parsing with a size limit AND validation:

```js
const { body, validationResult } = require('express-validator');

app.use(express.json({ limit: '10kb' })); // Reject oversized bodies

// Example on a POST route
app.post('/users',
  requireAuth,
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.body here
  }
);
```

