// Structured access logging
app.use(morgan('combined')); // or use winston/pino for structured JSON logs

// For sensitive routes, log access explicitly
app.get('/users', requireAuth, (req, res) => {
  console.log({ event: 'users_list_accessed', userId: req.user.id, ip: req.ip });
  // ...
});
```

