const app = express();
```

**Fix:** Add `helmet` as the very first middleware:

```js
const helmet = require('helmet');

// ✅ Sets 14+ security headers automatically
app.use(helmet());

// Or granularly:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: { maxAge: 31536000, includeSubDomains: true },
}));
```

