**Recommended fix — establish safe defaults now:**
```js
const express = require('express');
const { body, param, query, validationResult } = require('express-validator'); // npm install express-validator

app.use(express.json({ limit: '10kb' })); // Parse JSON bodies, cap size to prevent DoS
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Reusable validation error handler
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({ errors: errors.array() });
  }
  next();
}

// Example: safe future POST route with validation
app.post('/users',
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  validate,
  (req, res) => {
    // req.body is now sanitized before it touches any DB or business logic
