**Recommendation:** Add an authentication middleware (JWT shown here; adapt to your auth strategy):

```js
const jwt = require('jsonwebtoken');

// Reusable auth middleware
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Missing authentication token' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ✅ FIXED — route is now protected
app.get('/users', requireAuth, (req, res) => {
  res.json([...]);
});
```

---

### 🔴 CRITICAL — Finding 2: Secrets Have No Safe Loading Mechanism

**File:** `app.js` (absence of secret management)  
**OWASP:** A02:2021 – Cryptographic Failures / Secret Exposure

The app has no `dotenv` or secrets management setup at all. Given the presence of a `.env.test` file in the same directory, secrets could easily be accidentally committed or loaded insecurely.

**Recommendation:** Load secrets safely with validation at startup, and ensure `.env` files are always gitignored:

```js
// At the very top of app.js, before anything else
require('dotenv').config();

// Validate required secrets are present before the server starts
const REQUIRED_ENV_VARS = ['JWT_SECRET', 'DATABASE_URL'];
const missing = REQUIRED_ENV_VARS.filter((key) => !process.env[key]);
if (missing.length > 0) {
  console.error(`FATAL: Missing required environment variables: ${missing.join(', ')}`);
  process.exit(1);
}
```

```bash
# .gitignore — this MUST exist
.env
.env.*
!.env.example
```

---

### 🔴 CRITICAL — Finding 3: No Rate Limiting — Denial of Service & Brute Force

**File:** `app.js` (absence of rate limiting)  
**OWASP:** A05:2021 – Security Misconfiguration / A04 Insecure Design

There is zero rate limiting. Any endpoint (especially future auth endpoints) can be hammered indefinitely.

**Recommendation:**

```js
const rateLimit = require('express-rate-limit');

// Global limiter for all routes
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,   // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

// Stricter limiter for sensitive endpoints (e.g., login, /users)
const sensitiveRouteLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Rate limit exceeded on sensitive endpoint.' },
});

app.use(globalLimiter);
app.get('/users', sensitiveRouteLimiter, requireAuth, (req, res) => { ... });
```

---

### 🟠 HIGH — Finding 4: Missing Security Headers

**File:** `app.js` (absence of HTTP security headers)  
**OWASP:** A05:2021 – Security Misconfiguration

Express ships with no protective HTTP headers by default. This leaves the app open to clickjacking, MIME sniffing, and XSS via browser-level attacks.

**Recommendation:** Add `helmet` as the very first middleware:

```js
const helmet = require('helmet');

// Must be registered BEFORE all other middleware and routes
app.use(helmet());

// helmet() sets all of the following automatically:
//   Content-Security-Policy
//   X-DNS-Prefetch-Control
//   X-Frame-Options: SAMEORIGIN       (anti-clickjacking)
//   X-Content-Type-Options: nosniff   (anti-MIME-sniffing)
//   Referrer-Policy
//   Strict-Transport-Security (HSTS)
//   X-XSS-Protection
```

---

### 🟠 HIGH — Finding 5: No Request Body Parsing or Input Validation

**File:** `app.js` (absence of body parsing + validation)  
**OWASP:** A03:2021 – Injection

The app has no `express.json()` middleware and no input validation. Any POST/PUT routes added in the future will silently receive `undefined` bodies, and there is no schema enforcement anywhere. This is a direct path to injection vulnerabilities.

**Recommendation:**

```js
const { body, query, param, validationResult } = require('express-validator');

// Register body parsers with size limits to prevent payload flooding
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Reusable validation error handler
function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example: validated POST /users route
app.post(
  '/users',
  requireAuth,
  [
    body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
  ],
  validateRequest,
  (req, res) => {
    const { name, email } = req.body; // safe to use
    res.status(201).json({ name, email });
  }
);
```

---

### 🟠 HIGH — Finding 6: No CORS Policy

**File:** `app.js` (absence of CORS configuration)  
**OWASP:** A05:2021 – Security Misconfiguration

Without explicit CORS headers, browser-based clients may behave unpredictably, and when CORS is eventually added ad-hoc (e.g., `Access-Control-Allow-Origin: *`), it will permit any origin to make credentialed requests.

**Recommendation:**

```js
const cors = require('cors');

const corsOptions = {
  origin: (origin, callback) => {
    const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '').split(',');
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS policy violation: origin '${origin}' not allowed`));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // Cache preflight for 24h
};

app.use(cors(corsOptions));
```

