  res.json({ status: 'ok' });
});

// Separate authenticated status endpoint for internal monitoring
app.get('/status', requireAuth, (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
