const morgan = require('morgan');

// Structured request logging (use 'combined' format in production for full detail)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// For sensitive routes, add explicit security event logging
function logSecurityEvent(event, req, detail = {}) {
  console.warn(JSON.stringify({
    type: 'SECURITY_EVENT',
    event,
    ip: req.ip,
    userAgent: req.headers['user-agent'],
    url: req.url,
    timestamp: new Date().toISOString(),
    ...detail,
  }));
}

